document.addEventListener('keydown',e=>{if(e.code==='Escape'&&openPanel){showPanel(openPanel);return;}if(!$('scenarioChooser').hidden)return;if((['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)||(['BUTTON','A'].includes(document.activeElement.tagName)&&['Space','Enter','Tab'].includes(e.code)))||($('help').open||$('missions').open))return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Tab'].includes(e.code)&&(e.target===document.body||e.target===canvas))e.preventDefault();if(e.code==='Tab'&&(e.target===document.body||e.target===canvas)){toggleHUD();return;}keys.add(e.code);if(e.repeat)return;if(e.code==='Space'&&!state.started)launch();if(e.code==='KeyO')toggleOrbits();if(e.code==='KeyX')setSpeed(0);if(e.code==='KeyG')align();if(e.code==='KeyN')toggleNav();if(e.code==='KeyV')showPanel('cockpit');if(e.code==='KeyB')showPanel('systems');if(e.code==='KeyM')setMark(['target','all','none'][(['target','all','none'].indexOf(state.mark)+1)%3]);if(e.code==='KeyP')pause();if(e.code==='KeyH')showHelp();});document.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();drag=false;});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();last=performance.now();if(state.started&&!state.paused)pause();}});
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_flight_state',description:'Read the exploration scenario, physical speed and solar or relativistic clocks.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({ready:state.ready,scenario:state.scenario,phase:state.phase,speedKmS:state.speed,maxSpeedKmS:state.scenario==='blackhole'?BH_MAX_SPEED:MAX_SPEED,playerProperSeconds:state.scenario==='blackhole'?blackHole.proper:null,referenceSeconds:state.scenario==='blackhole'?blackHole.reference:null,utc:new Date(state.sim).toISOString(),target:state.target,timeMultiplier:state.warp})});document.modelContext.registerTool({name:'select_flight_destination',description:'Select a navigation marker without moving the ship.',inputSchema:{type:'object',properties:{body:{type:'string',enum:bodies.map(b=>b.id)}},required:['body'],additionalProperties:false},execute:input=>{if(!input||typeof input.body!=='string'||!objects.has(input.body))throw Error('Unknown body');setTarget(input.body);return{target:state.target};}});}catch(e){console.warn('WebMCP unavailable',e);}}

const gallery=new MissionGallery($('missions'),renderer instanceof SoftwareRenderer);$('missionButton').onclick=()=>{keys.clear();document.exitPointerLock?.();gallery.open();};$('quality').onchange=e=>{renderer.quality=e.target.value;blackHole.view.quality=e.target.value;renderer.last=0;e.target.blur();toast(e.target.value==='high'?'Calidad alta · mayor resolución y coste de renderizado':'Calidad adaptativa · más detalle al detener la mirada');};
